<script lang="ts">
 import {languageOverrides} from "./localization";
 import type {Project} from './model';import {uid,projectSchema} from './model';import {makeAdministrationDocument,administrationRow,saveAdministrationDocument} from './administration';import {accountOpenInMonth} from './account-lifecycle';import {serviceBalanceReport,UNALLOCATED_SERVICE} from './service-reports';import {allocatePayment} from './payment-allocation';import {D,money} from './engine';import {displayPeriod} from './date-format';import {openReportLookup} from './report-settings';import {translator} from './i18n';import LineToolbar from './LineToolbar.svelte';import AccountLookupField from './AccountLookupField.svelte';import {Calculator,X} from "./icons";
 export let project:Project;export let recalculate=false;export let onapply:(p:Project)=>void;export let onclose:()=>void;
 let recalculationPeriod=project.settings.period,recalculateBenefits=true,accounts:string[]=[],selected=0,chargeServices=true,chargePenalties=false,advance=false,rate='0',days=0,penaltyService='',error='',result='';$:t=translator(project.settings.language,$languageOverrides);
 function pick(){openReportLookup({id:'group-charge-'+(recalculate?'recalc':'new'),parentId:recalculate?'batch-recalculation':'batch-charges',label:t('Лицевые счета','Conturi personale'),items:project.accounts.map(a=>({id:a.id,code:a.number,name:a.payer_name,address:a.address})),selected:accounts,multiple:true,kind:'accounts',onchoose:ids=>accounts=ids});}
 function move(delta:number){const i=selected+delta;if(i<0||i>=accounts.length)return;const copy=[...accounts];[copy[i],copy[selected]]=[copy[selected],copy[i]];accounts=copy;selected=i;}
 function run(){try{if(new Set(accounts).size!==accounts.length)throw Error(t('Лицевой счёт повторяется.','Contul personal se repetă.'));if(!accounts.length||!chargeServices&&!(recalculate?recalculateBenefits:chargePenalties))throw Error(t('Выберите счета и виды начислений.','Selectați conturile și tipurile de calcul.'));let next=structuredClone(project);let count=0;for(const id of accounts){if(chargeServices||recalculate&&recalculateBenefits){const doc=makeAdministrationDocument(next,recalculate?'recalculation':'service-charges');doc.rows=[{...administrationRow(next),account_id:id}];if(recalculate){doc.recalculation_period=recalculationPeriod;doc.recalculate_services=chargeServices;doc.recalculate_benefits=recalculateBenefits;}next=saveAdministrationDocument(next,doc,true);count++;}if(chargePenalties){const debt=serviceBalanceReport(next,project.settings.period,project.settings.period,'',false,true).rows.filter(r=>r.account_id===id).reduce((sum,r)=>sum.plus(D(r.opening).gt(0)?r.opening:0),D(0));const doc=makeAdministrationDocument(next,'penalties');doc.rows=[{...administrationRow(next),account_id:id,service_id:penaltyService,quantity:money(debt,next),rate,days}];next=saveAdministrationDocument(next,doc,true);count++;}if(advance){const balances=serviceBalanceReport(next,project.settings.period,project.settings.period,'',false,true).rows.filter(r=>r.account_id===id);if(balances.some(r=>r.service_id===UNALLOCATED_SERVICE&&!D(r.closing).isZero()))throw Error(t('Сначала распределите прежние суммы по услугам.','Repartizați mai întâi sumele anterioare pe servicii.'));const credits=balances.filter(r=>D(r.closing).lt(0)),debts=balances.filter(r=>D(r.closing).gt(0)),credit=credits.reduce((s,r)=>s.minus(r.closing),D(0)),debt=debts.reduce((s,r)=>s.plus(r.closing),D(0)),available=credit.lt(debt)?credit:debt;if(available.gt(0)){const doc=makeAdministrationDocument(next,'charge-corrections');doc.comment=t('Распределение аванса между услугами','Repartizarea avansului între servicii');const splits=allocatePayment(next,debts.map(r=>({service_id:r.service_id,debt:r.closing})),money(available,next),debts[0].service_id);doc.rows=splits.filter(s=>!D(s.amount).isZero()).map(s=>({...administrationRow(next),account_id:id,service_id:s.service_id,amount:D(s.amount).negated().toFixed(2)}));let left=available;for(const c of credits){const limit=D(c.closing).negated(),value=left.lt(limit)?left:limit;if(value.gt(0))doc.rows.push({...administrationRow(next),account_id:id,service_id:c.service_id,amount:money(value,next)});left=left.minus(value);}next=saveAdministrationDocument(next,doc,true);count++;}}}onapply(projectSchema.parse(next));result=t('Создано и проведено документов: ','Documente create și aplicate: ')+count;error='';}catch(e){error=e instanceof Error?e.message:String(e);}}
</script>
<div class="group-charge-process"><label>{t('Текущий период','Perioada curentă')}<input readonly value={displayPeriod(project.settings.period,project)}/></label><div class="checks"><label class="check-row"><input type="checkbox" bind:checked={chargeServices}/>{recalculate?t('Пересчитать услуги','Recalculează servicii'):t('Начислять за услуги','Calculează servicii')}</label>{#if recalculate}<label class="check-row"><input type="checkbox" bind:checked={recalculateBenefits}/>{t('Перерассчитывать льготы','Recalculează facilitățile')}</label>{:else}<label class="check-row"><input type="checkbox" bind:checked={chargePenalties}/>{t('Начислять пени','Calculează penalități')}</label>{/if}</div>{#if recalculate}<label>{t('Перерассчитываемый период','Perioada recalculată')}<input type="month" bind:value={recalculationPeriod}/></label>{/if}<label>{t('Способ распределения аванса','Metoda repartizării avansului')}<select bind:value={advance}><option value={false}>{t('Не перераспределять','Nu repartiza')}</option><option value={true}>{t('Пропорционально долгу по услугам','Proporțional datoriei pe servicii')}</option></select></label>{#if chargePenalties}<fieldset><legend>{t('Пеня на положительный долг на начало месяца','Penalitate pentru datoria pozitivă la începutul lunii')}</legend><label>{t('Услуга для пени','Serviciu pentru penalitate')}<AccountLookupField {project} kind="services" value={penaltyService} parentId={recalculate?'batch-recalculation':'batch-charges'} onselect={id=>penaltyService=id}/></label><label>{t('Процент в день','Procent pe zi')}<input inputmode="decimal" bind:value={rate}/></label><label>{t('Дней','Zile')}<input type="number" min="0" max="3660" bind:value={days}/></label></fieldset>{/if}<strong>{t('Список лицевых счетов','Lista conturilor personale')}</strong><LineToolbar language={project.settings.language} selected={accounts.length>0} onadd={()=>accounts=[...accounts,'']} oncopy={undefined} onremove={()=>accounts=accounts.filter((_,i)=>i!==selected)} onmove={move} onpick={pick} onfill={()=>accounts=project.accounts.filter(a=>accountOpenInMonth(a,project.settings.period)).map(a=>a.id)} onclear={()=>accounts=[]}/><div class="table-wrap"><table><thead><tr><th>{t('Лицевой счёт','Cont personal')}</th></tr></thead><tbody>{#each accounts as id,i}<tr class:selected={i===selected} onclick={()=>selected=i}><td><AccountLookupField {project} kind="accounts" value={id} parentId={recalculate?'batch-recalculation':'batch-charges'} onselect={id=>accounts=accounts.map((a,j)=>i===j?id:a)}/></td></tr>{/each}</tbody></table></div>{#if error}<p class="alert error" role="alert">{error}</p>{/if}{#if result}<p role="status">{result}</p>{/if}<footer><button class="button" onclick={run}><Calculator size={16}/>{recalculate?t('Пересчитать','Recalculează'):t('Начислить','Calculează')}</button><button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer></div>
<style>.group-charge-process{display:flex;flex-direction:column;gap:16px;padding:22px;min-height:100%;box-sizing:border-box}.group-charge-process>label,fieldset>label{display:grid;grid-template-columns:220px minmax(0,1fr);gap:12px;align-items:center}.checks,footer{display:flex;gap:16px}footer{justify-content:flex-end;margin-top:auto}.table-wrap{flex:1;min-height:200px}.selected{background:var(--hover)}fieldset{display:grid;gap:12px;border:1px solid var(--border);padding:14px}</style>
